"""llms.txt / sitemap.xml / robots.txt: generated by refresh.py from the data,
so their counts and section list can't drift from the site."""

from __future__ import annotations

import json
import re
from pathlib import Path

import refresh

ROOT = Path(__file__).resolve().parent.parent
DOCS = ROOT / "docs"
APP_JS = (DOCS / "app.js").read_text(encoding="utf-8")


def test_agent_files_cover_every_view() -> None:
    m = re.search(r"const VIEWS\s*=\s*\[(.*?)\]", APP_JS, re.DOTALL)
    assert m
    views = set(re.findall(r'"([a-z]+)"', m.group(1)))
    assert views == set(refresh.VIEW_GUIDE), views ^ set(refresh.VIEW_GUIDE)


def test_llms_txt_counts_match_home() -> None:
    text = (DOCS / "llms.txt").read_text(encoding="utf-8")
    totals = json.loads((DOCS / "data" / "home.json").read_text(encoding="utf-8"))["totals"]
    assert text.startswith("# Data Center Community Benefits\n\n> ")
    for key in ("sites", "moratoriums", "policies", "tariffs", "rate_cases"):
        label = key.replace("_", " ")
        assert re.search(rf"\b{totals[key]} {label}\b", text), key


def test_llms_txt_lists_every_data_file() -> None:
    text = (DOCS / "llms.txt").read_text(encoding="utf-8")
    for f in sorted((DOCS / "data").glob("*.json")):
        assert f"data/{f.name}" in text, f.name


def test_sitemap_and_robots() -> None:
    sm = (DOCS / "sitemap.xml").read_text(encoding="utf-8")
    assert refresh.SITE_URL in sm and "llms.txt" in sm
    assert "Sitemap: " + refresh.SITE_URL + "sitemap.xml" in (DOCS / "robots.txt").read_text()


def test_index_has_canonical_and_structured_data() -> None:
    html = (DOCS / "index.html").read_text(encoding="utf-8")
    assert f'rel="canonical" href="{refresh.SITE_URL}"' in html
    m = re.search(r'<script type="application/ld\+json">(.*?)</script>', html, re.DOTALL)
    assert m and json.loads(m.group(1))["@type"] == "Dataset"
